package main

import "fmt"

type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func newNode(val int) *TreeNode {
	return &TreeNode{Val: val}
}

// Safe tree operations
func (n *TreeNode) Height() int {
	if n == nil {
		return 0
	}
	leftH := n.Left.Height()
	rightH := n.Right.Height()
	if leftH > rightH {
		return 1 + leftH
	}
	return 1 + rightH
}

func (n *TreeNode) Sum() int {
	if n == nil {
		return 0
	}
	return n.Val + n.Left.Sum() + n.Right.Sum()
}

func (n *TreeNode) InOrder() []int {
	if n == nil {
		return nil
	}
	result := n.Left.InOrder()
	result = append(result, n.Val)
	result = append(result, n.Right.InOrder()...)
	return result
}

// Safe dereferencing helpers
func derefInt(p *int, def int) int {
	if p == nil {
		return def
	}
	return *p
}

func derefString(p *string, def string) string {
	if p == nil {
		return def
	}
	return *p
}

func main() {
	// Binary tree:
	//       4
	//      / \
	//     2   6
	//    / \ / \
	//   1  3 5  7
	root := newNode(4)
	root.Left = newNode(2)
	root.Right = newNode(6)
	root.Left.Left = newNode(1)
	root.Left.Right = newNode(3)
	root.Right.Left = newNode(5)
	root.Right.Right = newNode(7)

	fmt.Println("Tree height:", root.Height())
	fmt.Println("Tree sum:", root.Sum())
	fmt.Println("In-order:", root.InOrder())

	// Nil tree is safe
	var nilTree *TreeNode
	fmt.Println("Nil tree height:", nilTree.Height())
	fmt.Println("Nil tree sum:", nilTree.Sum())

	// Safe deref helpers
	var age *int
	name := "Alice"

	fmt.Println("Age:", derefInt(age, -1))
	fmt.Println("Name:", derefString(&name, "unknown"))

	val := 42
	fmt.Println("Val:", derefInt(&val, -1))
}
